Here is a simple React component that provides autocomplete functionality without relying on other third-party packages:
```
import React, { useState, useEffect } from 'react';

const Autocomplete = ({ suggestions, onChange }) => {
  const [inputValue, setInputValue] = useState('');
  const [suggestionsList, setSuggestionsList] = useState([]);
  const [activeSuggestionIndex, setActiveSuggestionIndex] = useState(-1);

  useEffect(() => {
    const timer = setTimeout(() => {
      if (inputValue.trim() !== '') {
        const filteredSuggestions = suggestions.filter((suggestion) => {
          return suggestion.toLowerCase().includes(inputValue.toLowerCase());
        });
        setSuggestionsList(filteredSuggestions);
      } else {
        setSuggestionsList([]);
      }
    }, 500);

    return () => {
      clearTimeout(timer);
    };
  }, [inputValue, suggestions]);

  const handleInputChange = (event) => {
    setInputValue(event.target.value);
  };

  const handleSuggestionClick = (suggestion) => {
    onChange(suggestion);
    setInputValue(suggestion);
    setActiveSuggestionIndex(-1);
  };

  const handleClickOutside = (event) => {
    if (!event.target.parentNode.contains(event.target)) {
      setActiveSuggestionIndex(-1);
    }
  };

  return (
    <div>
      <input
        type="text"
        value={inputValue}
        onChange={handleInputChange}
        onKeyDown={(event) => {
          if (event.key === 'ArrowDown') {
            setActiveSuggestionIndex((activeSuggestionIndex + 1) % suggestionsList.length);
          } else if (event.key === 'ArrowUp') {
            setActiveSuggestionIndex(
              (activeSuggestionIndex - 1 + suggestionsList.length) % suggestionsList.length
            );
          } else if (event.key === 'Enter') {
            const suggestion = suggestionsList[activeSuggestionIndex];
            handleSuggestionClick(suggestion);
          }
        }}
        onClick={(event) => {
          event.stopPropagation();
        }}
      />
      {suggestionsList.length > 0 && (
        <ul
          className="autocomplete-suggestions"
          onClick={(event) => handleClickOutside(event)}
        >
          {suggestionsList.map((suggestion, index) => (
            <li
              key={index}
              className={`autocomplete-suggestion ${index === activeSuggestionIndex ? 'active' : ''}`}
              onClick={() => handleSuggestionClick(suggestion)}
            >
              {suggestion}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default Autocomplete;
```
