To solve this PDE, we'll use the finite difference method (FDM) with some C++ code. The main steps are:

1. Discretize the spatial and temporal domains using a grid.
2. Approximate the derivatives using finite differences.
3. Implement the boundary conditions.
4. Numerically integrate the PDE using the discretized versions of the derivatives.

Here's the C++ code to get you started:
```cpp
#include <iostream>
#include <cmath>
#include <vector>

// Constants
const double alpha = 0.01; // adjust this value
const double gamma = 0.02; // adjust this value
const double mu = 1e-3; // adjust this value
const double zeta = 1.0; // adjust this value
const double T_max = 10.0; // adjust this value (final time)
const double Z_max = 100.0; // adjust this value (x-boundary)

// Function definitions
double M(double zeta, double h, double alpha) {
  return (zeta * alpha * alpha * alpha * alpha) / (16 * mu) *
         (3 * pow(1 + h / (alpha * zeta), 4) -
          4 * pow(1 + h / (alpha * zeta), 2) + 1 -
          4 * pow(1 + h / (alpha * zeta), 4) * log(1 + h / (alpha * zeta)));
}

double p(double h, double dh_dz, double dh_dz2) {
  return -gamma * (dh_dz2 / (1 + pow(dh_dz, 2))^(3 / 2) -
                     (1 - alpha * dh_dz) / ((alpha * zeta + h) * pow(1 + pow(dh_dz, 2), 1 / 2)));
}

// FDM discretization
int main() {
  // Set up the grid
  int Nx = 100;
  int Nt = 1000;
  double dz = Z_max / (Nx - 1);
  double dt = T_max / (Nt - 1);
  std::vector<double> h(Nx), p(Nx);
  std::vector<double> M_values(Nx);

  // Initial conditions
  for (int i = 0; i < Nx; ++i) {
    h[i] = 50e-6 + 162e-6 * (1 - tanh((i - 30) * dz));
    p[i] = 0.022 / (20e-6); // adjust this value
  }
  h[0] = 50e-6; // adjust this value

  // Boundary conditions
  for (int t = 0; t < Nt; ++t) {
    for (int i = 0; i < Nx; ++i) {
      M_values[i] = M(dz * i, h[i], alpha);
    }
    for (int i = 1; i < Nx - 1; ++i) {
      double fh = (h[i + 1] - h[i - 1]) / (2 * dz);
      double fdh_dz = (h[i + 1] - 2 * h[i] + h[i - 1]) / dz / dz;
      double fdh_dz2 = (h[i + 1] - 2 * h[i] + h[i - 1]) / dz / dz;
      p[i] = p(h[i], fdh_dz, fdh_dz2);
    }

    // Time integration
    for (int i = 1; i < Nx - 1; ++i) {
      double dh_dt = (1 / (M_values[i] * alpha + h[i])) *
                     ((M_values[i - 1] * h[i - 1] - M_values[i + 1] * h[i + 1]) / dz /
                      (M_values[i] * alpha + h[i]));
      h[i] += dt * dh_dt;
    }

    // Plot the results (optional)
    // ...
  }

  return 0;
}
```
