class PasswordGenerator {
  constructor(options = {}) {
    this.length = options.length || 12; // Longitud default de la contraseña
    this.useUpperCase = options.useUpperCase || true; // Utilizar mayúsculas
    this.useNumbers = options.useNumbers || true; // Utilizar números
