    if (this.useUpperCase) {
      characters.push.apply(characters, this.getCharactersFromRange("A", "Z"));
    }
    if (this.useNumbers) {
      characters.push.apply(characters, this.getCharactersFromRange("0", "9"));
    }
    if (this.useSpecialChars) {
      characters.push.apply(characters, this.getSpecialCharacters());
    }
    for (let i = 0; i < this.length; i++) {
      password += characters[Math.floor(Math.random() * characters.length)];
    }
