    const characters = [];
    for (let i = min.charCodeAt(0); i <= max.charCodeAt(0); i++) {
      characters.push(String.fromCharCode(i));
    }
    return characters;
  }

  getSpecialCharacters() {
    return [
      "!", "@", "#", "$", "%", "^", "&", "*", "_", "-", "+", "=,", "~", "`";
