#include <boost/interprocess/ipc/message_queue.hpp>
#include <boost/interprocess/ipc/shared_memory_object.hpp>
#include <boost/interprocess/ipc/notify_flags.hpp>
#include <iostream>

using namespace std;
using namespace boost::interprocess;

int main() {
    // Initialize shared memory
    shared_memory_object shm(create_only, "my_shm", read_write);
    shm.truncate(1024);

    // Initialize message queue
    message_queue mq(create_only, "my_mq", 100, sizeof(int));

    // Write data to shared memory
    void * addr = shm.get_address();
    int * data = reinterpret_cast<int*>(addr);
    *data = 123;

    // Send message to message queue
    int message = 456;
    mq.send(&message, sizeof(int));

    // Notify `syncer2` that data is available
    notify_flags notify(shm, notify_flags::insert);

    return 0;
}
```

