#include <boost/interprocess/ipc/notify_flags.hpp>
#include <iostream>

using namespace std;
using namespace boost::interprocess;

int main() {
    // Open shared memory
    shared_memory_object shm(open_only, "my_shm", read_write);

    // Open message queue
    message_queue mq(open_only, "my_mq");

    // Wait for data to become available
    notify_flags notify(shm, notify_flags::wait);

    // Read data from shared memory
    void * addr = shm.get_address();
    int * data = reinterpret_cast<int*>(addr);
    int value = *data;
    cout << "Received data: " << value << endl;

    // Remove data from shared memory
    *data = 0;

    // Receive message from message queue
    int message;
    mq.receive(&message, sizeof(int));
    cout << "Received message: " << message << endl;

    return 0;
}
